// ============================================================================
// 【A-1】Framer Coverflow — 可上架元件(自動播放版;互動 drag/cursor 留 A-2)
//
// 延續 spike/framer-coverflow。目標:圖片能傳、參數齊、拖進來就漂亮、會自動
// 播放。不做互動(A-2)、不做多模板(只 coverflow)。
//
// 引擎:computeCardTransforms 用互動波合流後的【4-arg 版】,原樣內聯自
// src/templates/coverflow/coverflowMath.js;render 呼叫 (config, t, t, 0)
// → tPos≡tAmb≡t、dragVel=0,純自動播放。數學已對照真引擎逐位元驗過
// (見附帶 coverflow-parity 測,含本輪 7 個開放參數值域掃描 max Δ=0)。
//
// ⚠️【DOM 透視鏈忠實】層數與 app 一致、不精簡:
//   scene(abs,inset:0)
//   └ offset(abs,inset:0,transform-style:preserve-3d,translate)
//     └ group(abs,inset:0,transform-style:FLAT override,scale;量測 canvasWidth)
//       └ card(abs,left:50%→每幀覆蓋 px,top:50%,overflow:hidden)
//         └ img(100%×100%,object-fit:cover)
//   per-card 每幀(修正單: 定位樓梯抖動 — 整數留 left、小數餘數走 transform x):
//     el.style.left = `${Math.floor(tr.left)}px`;transform =
//     `perspective(${tr.perspective}px) translate3d(${tr.left-Math.floor(tr.left)}px,-50%,${tr.z}px)`
//     + (rotateY?) + ` scale(${tr.scale})`   —— 每卡自帶 perspective(),
//   非容器 perspective;autoplay 下 rotateX/rotateZ 恆 0,照 app 條件式省略。
//
// 策展:開放 8 個 property controls(count/cardSize/gap/duration/zoom/
// cardRatio/cornerRadius/focusEmphasis),其餘全部鎖死為 coverflow 預設 preset
// 的性格骨架值(sideRotation -49、depthFalloff 14、ease expo.out、cycles 1、
// offset 0、perspective 2000、direction forward、motion step)。cornerRadius
// 是策展的圓角(直接 px,不影響 coverflow 性格),故開放。
// ============================================================================

import {
    useCallback,
    useEffect,
    useLayoutEffect,
    useMemo,
    useRef,
    useState,
} from "react"
// Standalone Framer Shim for Next.js / React
const useIsStaticRenderer = () => false;
const addPropertyControls = () => {};
const ControlType = {
    Boolean: 'boolean', Number: 'number', String: 'string',
    Color: 'color', Enum: 'enum', Object: 'object',
    Array: 'array', Image: 'image', ResponsiveImage: 'responsiveImage',
    Font: 'font', Transition: 'transition', Link: 'link'
};


// ----------------------------------------------------------------------
// 常數 —— 原樣抄自 coverflowMath.js(同名同值)。
// ----------------------------------------------------------------------
const PERSPECTIVE_PX_DEFAULT = 2000
const FOCUS_WINDOW_STEPS = 1
const DEPTH_FALLOFF_MIN_SCALE = 0.32
const DEPTH_FALLOFF_SCALE_RATE = 0.007
const DEPTH_FALLOFF_Z_RATE = 3
const FOCUS_EMPHASIS_MAX_Z = 760
const Z_INDEX_RESOLUTION = 1000
const Z_INDEX_BASE = 100000

// coverflow 預設 preset 的【性格骨架】——不開放,鎖死。開放的 7 個由 props 覆蓋。
const LOCKED = {
    sideRotation: -49,
    depthFalloff: 14,
    direction: "forward" as const,
    motion: "step" as const,
    // ease 鎖死 'expo.out',見 expoOut()。
    cycles: 1,
    offsetX: 0,
    offsetY: 0,
    perspective: 2000,
}

// 響應式 fit 層(Framer 專屬)。coverflow 在一個設計空間裡算(canvasWidth 固定
// = DESIGN_W 1080,對齊 app 的水平設計寬),再把設計畫布【contain 等比縮放】
// (同 app PreviewCanvas 的 `Math.min(w/dw, h/dh)`)到 frame、置中。fit 是純外層
// CSS 縮放,不碰 computeCardTransforms 的數值(仍在 1080 設計空間裡算)。
//
// 【自動 aspect】DESIGN_H 不固定,而是【跟隨 frame 比例】(DESIGN_H =
// 1080×frameH/frameW)→ 設計畫布與 frame 同比例 → contain 剛好貼滿、無多餘留白
// (= app 靠手動切 1:1 / 16:9 aspect 達到的效果,這裡自動化)。但加一個【焦點卡
// 高度地板】:frame 極寬(>~2.7:1)時 DESIGN_H 會小於焦點卡 → 用地板撐住,
// 焦點卡永不被裁、且留 ~15% breathing(FOCUS_BREATHING)。zoom 仍是作者控制,
// 套 group → 總縮放 = fitScale × (zoom/100)。
const DESIGN_W = 1080
// 焦點卡最多佔設計畫布高度的比例(留 ~15% 上下 breathing,焦點卡不頂到邊)。
const FOCUS_BREATHING = 0.85

// A-2 互動:wrapTime 逐字抄自 useCardTransformTimeline.js / embedExport.js。
const wrapTime = (t: number, d: number) => ((t % d) + d) % d

// ease 鎖死為 coverflow preset 的 'expo.out'。純數學等式,【逐位元】等於
// gsap.parseEase('expo.out')——關鍵:GSAP 的 Expo easeIn 是
//   Math.pow(2,10*(x-1))*x + x*x*x*x*x*x*(1-x)   (gsap.js:1469)
// 且 easeOut(p)=1-easeIn(1-p)(gsap.js:1366)。⚠️ 必須用 x*x*x*x*x*x 而非
// Math.pow(x,6),否則差 1 ULP 就不再逐位元一致(這正是 spike 那種 ease 陷阱)。
// 已驗:1M 取樣對 gsap max Δ=0。
function expoOut(p: number): number {
    const x = 1 - p
    const expoIn =
        Math.pow(2, 10 * (x - 1)) * x + x * x * x * x * x * x * (1 - x)
    return 1 - expoIn
}

interface CoverflowConfig {
    count: number
    cardSize: number
    cardRatio: string
    cornerRadius: number
    gap: number
    sideRotation: number
    depthFalloff: number
    focusEmphasis: number
    direction: "forward" | "reverse"
    motion: "continuous" | "step"
    cycles: number
    duration: number
    perspective: number
    canvasWidth: number
}

interface CardTransform {
    left: number
    y: number
    z: number
    scale: number
    rotateY: number
    rotation: number
    opacity: number
    perspective: number
    zIndex: number
}

// --- 原樣抄自 coverflowMath.js ---
function focusWindow(d: number): number {
    const ad = Math.abs(d)
    if (ad >= FOCUS_WINDOW_STEPS / 2) return 0
    return 0.5 * (1 + Math.cos((Math.PI * d) / (FOCUS_WINDOW_STEPS / 2)))
}

function cardStyleAt(d: number, config: CoverflowConfig) {
    const { sideRotation, focusEmphasis, depthFalloff } = config
    const w = focusWindow(d)
    const ad = Math.abs(d)
    const baseScale = Math.max(
        DEPTH_FALLOFF_MIN_SCALE,
        1 - depthFalloff * DEPTH_FALLOFF_SCALE_RATE * ad
    )
    const scale = baseScale
    const rot = sideRotation * Math.sign(d) * (1 - w)
    const zRecede = -depthFalloff * DEPTH_FALLOFF_Z_RATE * ad
    const zLift = (focusEmphasis / 100) * FOCUS_EMPHASIS_MAX_Z * w
    return { scale, rot, z: zRecede + zLift }
}

function cardRenderHeight(config: CoverflowConfig): number {
    const { cardSize, cardRatio } = config
    const [ratioW, ratioH] = cardRatio.split(":").map(Number)
    return cardSize * (ratioH / ratioW)
}

// 【4-arg 版,原樣內聯自 coverflowMath.js】唯一改動:step 分支的
// getEaseFn(ease,easeCustom)(inStep) → expoOut(inStep)(ease 鎖死 expo.out,
// 逐位元等式,見上)。其餘每一行(wrap、footprint spacing、focus 內插、
// per-card left+perspective+z+rotateY+scale+zIndex)逐字未改。
function computeCardTransforms(
    config: CoverflowConfig,
    tPos: number,
    tAmb: number = tPos,
    dragVel: number = 0
): CardTransform[] {
    const {
        cardSize,
        gap,
        direction,
        motion,
        duration,
        cycles,
        count,
        perspective,
        canvasWidth,
    } = config
    const cw = canvasWidth || 1920
    const dirSign = direction === "reverse" ? -1 : 1
    const centerSlotIndex = (count - 1) / 2

    let focusAdvance: number
    if (motion === "step" && dragVel === 0) {
        const totalSteps = cycles * count
        const stepDuration = duration / totalSteps
        const s = tPos / stepDuration
        const stepIndex = Math.floor(s)
        const inStep = s - stepIndex
        const eased = expoOut(inStep)
        focusAdvance = dirSign * (stepIndex + eased)
        if (count % 2 === 0) {
            focusAdvance += 0.5
        }
    } else if (motion === "step") {
        focusAdvance = dirSign * cycles * count * (tPos / duration)
        if (count % 2 === 0) {
            focusAdvance += 0.5
        }
    } else {
        focusAdvance = dirSign * cycles * count * (tPos / duration)
    }

    const ds: number[] = []
    const styles: { scale: number; rot: number; z: number }[] = []
    for (let i = 0; i < count; i++) {
        const baseOffset = i - centerSlotIndex
        const raw = baseOffset - focusAdvance
        const wrapped =
            ((((raw + count / 2) % count) + count) % count) - count / 2
        ds.push(wrapped)
        styles.push(cardStyleAt(wrapped, config))
    }

    const order = ds.map((_, i) => i).sort((a, b) => ds[a] - ds[b])
    const footprints = styles.map(
        (s) => cardSize * Math.abs(Math.cos((s.rot * Math.PI) / 180))
    )
    const localPos = [0]
    for (let k = 1; k < order.length; k++) {
        const a = order[k - 1]
        const b = order[k]
        const spacing = Math.max(0, (footprints[a] + footprints[b]) / 2 + gap)
        localPos.push(localPos[k - 1] + spacing)
    }
    let focusK = order.findIndex((i) => ds[i] >= 0)
    let localPosAtFocus: number
    if (focusK <= 0) {
        localPosAtFocus = localPos[0]
    } else if (focusK >= order.length) {
        localPosAtFocus = localPos[localPos.length - 1]
    } else {
        const iAfter = order[focusK]
        const iBefore = order[focusK - 1]
        const span = ds[iAfter] - ds[iBefore]
        const frac = span > 0 ? (0 - ds[iBefore]) / span : 0
        localPosAtFocus =
            localPos[focusK - 1] +
            frac * (localPos[focusK] - localPos[focusK - 1])
    }

    const persp = perspective || PERSPECTIVE_PX_DEFAULT
    const cx = cw / 2
    const transforms: CardTransform[] = new Array(count)
    for (let k = 0; k < order.length; k++) {
        const i = order[k]
        const d = ds[i]
        const { scale, rot, z } = styles[i]
        const left = cx + (localPos[k] - localPosAtFocus) - cardSize / 2
        transforms[i] = {
            left,
            y: 0,
            z,
            scale,
            rotateY: rot,
            rotation: 0,
            opacity: 1,
            perspective: persp,
            zIndex: Math.round(Z_INDEX_BASE - Math.abs(d) * Z_INDEX_RESOLUTION),
        }
    }
    return transforms
}

// ----------------------------------------------------------------------
// 預設示範圖(做法 B fallback)——正式圖 webp,已降尺寸至 640px 寬內嵌
// ----------------------------------------------------------------------
// 買家還沒上傳圖 → 顯示這組內建示範圖(而非空白);有上傳 → 用買家的。
// 這 7 張是 Su 提供的正式圖(playground/framer/demo/),降尺寸到 640px 寬、
// 重編 webp、base64 內嵌 —— 元件自包含(單檔可貼、不掛外部 URL)。要換圖
// 只需替換下面陣列字串。webp base64 在 <img> / Framer 皆原生支援。
const DEMO_IMAGES: string[] = [
    "data:image/webp;base64,",
    "data:image/webp;base64,",
    "data:image/webp;base64,",
    "data:image/webp;base64,",
    "data:image/webp;base64,",
    "data:image/webp;base64,",
    "data:image/webp;base64,",
]

// ----------------------------------------------------------------------
// Component
// ----------------------------------------------------------------------

/**
 * @framerIntrinsicWidth 800
 * @framerIntrinsicHeight 600
 * @framerSupportedLayoutWidth any
 * @framerSupportedLayoutHeight any
 */
export default function CoverflowSpike(props: {
    images: string[]
    count: number
    cardSize: number
    gap: number
    duration: number
    zoom: number
    cardRatio: string
    cornerRadius: number
    focusEmphasis: number
    draggable: boolean
}) {
    const {
        images,
        count,
        cardSize,
        gap,
        duration,
        zoom,
        cardRatio,
        cornerRadius,
        focusEmphasis,
        draggable,
    } = props

    // 做法 B:有圖用買家的圖(濾掉空槽);沒有 → fallback 到內建預設示範圖。
    const provided = (Array.isArray(images) ? images : []).filter(Boolean)
    const effectiveImages = provided.length > 0 ? provided : DEMO_IMAGES

    // pool = count(app 端 poolSize===count);每槽內容循環取
    // effectiveImages[i % n](app 端 assets[i % assets.length] 同一慣例)。
    const poolSize = Math.max(0, Math.floor(count))

    const rootRef = useRef<HTMLDivElement>(null)
    const cardRefs = useRef<(HTMLDivElement | null)[]>([])
    // A-2 互動:driver 讀最新 config(不因 config 變就重建、重置 tAmb —— 對齊
    // app 的 configRef 模式),drive 狀態(offset/tAmb/…)存在 ref 裡跨 re-render
    // 持續(對齊 app gsap timeline 的 preserve-progress)。
    const configRef = useRef<CoverflowConfig | null>(null)
    const driveRef = useRef({
        offset: 0,
        extraRate: 0,
        tPos: 0,
        tAmb: 0,
        playing: true,
        isDragging: false,
        lastX: 0,
        lastMoveTime: 0,
        lastRate: 0,
        clockLast: 0,
    })
    // 量測【外層 frame】的寬高(不再量 group)。canvasWidth 改為固定的設計寬度
    // DESIGN_W;frame 尺寸只用來算 contain 的 fitScale。init 給 intrinsic 800×600。
    const [frame, setFrame] = useState({ w: 800, h: 600 })

    useLayoutEffect(() => {
        const el = rootRef.current
        if (!el) return
        const observer = new ResizeObserver(([entry]) => {
            setFrame({
                w: entry.contentRect.width,
                h: entry.contentRect.height,
            })
        })
        observer.observe(el)
        return () => observer.disconnect()
    }, [])

    // canvasWidth 固定 = DESIGN_W(1080):cx = 540,焦點卡置中於設計畫布;
    // fit 不進 config(它是純外層縮放,不影響每卡的 left/transform 數值)。
    const config: CoverflowConfig = useMemo(
        () => ({
            ...LOCKED,
            count: poolSize,
            cardSize,
            gap,
            duration,
            cardRatio,
            cornerRadius,
            focusEmphasis,
            canvasWidth: DESIGN_W,
        }),
        [
            poolSize,
            cardSize,
            gap,
            duration,
            cardRatio,
            cornerRadius,
            focusEmphasis,
        ]
    )
    configRef.current = config // driver 每幀讀最新 config(對齊 app configRef)

    const cardHeight = cardRenderHeight(config)
    // Corner Radius 是【直接的 px 值】(property unit "px",對齊買家直覺),不是
    // app schema 那種「min(邊)×百分比」語意 —— 這是策展參數,px 更好懂。上限用卡片
    // 較短邊的一半 clamp 住,避免超過半徑把卡壓成怪形(40px on min 60px card 仍安全)。
    const cardRadius = Math.min(
        cornerRadius,
        Math.min(cardSize, cardHeight) / 2
    )

    // 焦點卡在設計空間的【實際渲染高度】:layout 高 cardHeight × group 縮放
    // (zoom/100) × perspective 放大(焦點卡 z-lift 由 focusEmphasis 決定,越大越
    // 凸、投影放大越多)。以此定「高度地板」→ 焦點卡永不超過設計畫布 / 被裁。
    const zLift = (focusEmphasis / 100) * FOCUS_EMPHASIS_MAX_Z
    const perspFactor = LOCKED.perspective / (LOCKED.perspective - zLift)
    const focusCardRenderH = cardHeight * (zoom / 100) * perspFactor
    // DESIGN_H = 跟隨 frame 比例;但不小於「焦點卡高度 / FOCUS_BREATHING」的地板。
    const designH = Math.max(
        (DESIGN_W * frame.h) / frame.w,
        focusCardRenderH / FOCUS_BREATHING
    )
    // contain fit(對齊 app PreviewCanvas 的 Math.min(w/dw, h/dh))。一般比例下
    // designH = frame 比例 → fitScale = frameW/DESIGN_W(貼滿寬、無左右留白);
    // 極寬時地板讓 designH 變大 → fitScale 轉為由高度決定 → 焦點卡不被裁。
    const fitScale = Math.min(frame.w / DESIGN_W, frame.h / designH)

    // 靜態渲染情境凍結在 t=0 靜止單幀(不跑 rAF、不掛互動)。useIsStaticRenderer
    // 是 Framer 標準判定,涵蓋【畫布編輯態 + 匯出(export/thumbnail 產生)】——
    // 比舊的 RenderTarget.current()===canvas 多蓋到 export(Framer 審核明確要求:
    // 匯出時必須走靜態分支,不能跑動畫/互動)。只有真實 Preview / 發布後線上
    // (isStatic===false)才動、才可拖。
    const isStatic = useIsStaticRenderer()

    // A-2:每卡 DOM 寫入(整數 left + 小數餘數走 transform x —— 次像素修正,
    // 三渲染器 parity)。抽成穩定函式,自動播放靜幀與互動 driver 共用。
    const paint = useCallback(
        (cfg: CoverflowConfig, tPos: number, tAmb: number, dragVel: number) => {
            const transforms = computeCardTransforms(cfg, tPos, tAmb, dragVel)
            transforms.forEach((tr, i) => {
                const el = cardRefs.current[i]
                if (!el) return
                const leftInt = Math.floor(tr.left)
                const leftFrac = tr.left - leftInt
                el.style.left = `${leftInt}px`
                el.style.transform =
                    `perspective(${tr.perspective}px) ` +
                    `translate3d(${leftFrac}px, -50%, ${tr.z}px)` +
                    (tr.rotateY ? ` rotateY(${tr.rotateY}deg)` : "") +
                    (tr.rotation ? ` rotateZ(${tr.rotation}deg)` : "") +
                    ` scale(${tr.scale})`
                el.style.opacity = String(tr.opacity)
                el.style.zIndex = String(tr.zIndex)
            })
        },
        []
    )

    // 靜態渲染(Framer 畫布編輯態 + 匯出/thumbnail)凍結在 t=0 靜止單幀(不跑
    // rAF、不接互動);只有真實 Preview / 發布後才動、才可拖。此 effect 只管靜幀,
    // 隨 config 更新 —— 匯出時走的正是這條(有預設圖、看得出是 coverflow)。
    useEffect(() => {
        if (!(isStatic || poolSize === 0)) return
        paint(config, 0, 0, 0)
    }, [config, isStatic, poolSize, paint])

    // Preview / 發布:主 render/clock 迴圈 + drag/scroll driver。
    // ⚠ parity:常數 / 公式 / 衰減曲線一律【逐字抄自】useTimelineInteraction.js
    // (app)與 embedExport.js 的 buildInteractiveDriver(已移植的 vanilla 版),
    // 不憑感覺重設。cursor 不做(A-3)。deps 不含 config —— driver 讀 configRef
    // 最新值、drive 狀態存 driveRef,故 config 變不重置 tAmb(對齊 app
    // preserve-progress)。root 為元件根節點、恆掛載(非 late-mount,紀律 #1
    // 的 callback-ref 坑不適用;此處 useRef + effect 已保證 commit 後才綁)。
    useEffect(() => {
        if (isStatic || poolSize === 0) return
        const root = rootRef.current
        if (!root) return
        const d = driveRef.current
        d.isDragging = false
        d.clockLast = performance.now()
        if (!draggable) {
            // 純自動播放:清乾淨、playing 恆真 → 與現有自動播放版逐幀相同。
            d.playing = true
            d.offset = 0
            d.extraRate = 0
        }

        // ---- 常數:逐字抄自 useTimelineInteraction.js ----
        const IDLE_MS = 50
        const MAX_FLICK_ITEMS = 10
        const SENSITIVITY = 100
        const MOMENTUM = 50
        const FLICK_MIN_DURATION = 0.3
        const FLICK_MAX_DURATION = 2.2
        const DECAY_K_MULTIPLIER = 3
        const CONTINUOUS_DECAY_EPS = 0.015
        const STEP_DECAY_EPS = 0.04
        const getCoastT = (coastDuration: number, eps: number) =>
            -Math.log(eps) / (DECAY_K_MULTIPLIER / coastDuration)
        const rateAtElapsed = (
            amplitude: number,
            elapsed: number,
            coastDuration: number
        ) =>
            amplitude *
            Math.exp(-(DECAY_K_MULTIPLIER / coastDuration) * elapsed)
        const solveAmplitudeForDistance = (
            distance: number,
            coastDuration: number,
            eps: number
        ) => (distance * (DECAY_K_MULTIPLIER / coastDuration)) / (1 - eps)
        const sensitivityMult = Math.pow(2, (SENSITIVITY - 50) / 50)
        // coverflow「一格 Δt」= duration/(cycles×count)(getOneItemDeltaT;
        // coverflow poolSize===count)。deltaTPerPx 逐字抄自 app,讀最新 config。
        const oneItemDelta = () => {
            const c = configRef.current!
            return c.duration / (c.cycles * c.count)
        }
        const deltaTPerPx = () => {
            const c = configRef.current!
            return c.cardSize > 0
                ? (oneItemDelta() / c.cardSize) * sensitivityMult
                : 0
        }

        let raf = 0
        let releaseRaf = 0
        let idleRaf = 0
        let wheelTimer: ReturnType<typeof setTimeout> | 0 = 0

        const stopRelease = () => {
            if (releaseRaf) {
                cancelAnimationFrame(releaseRaf)
                releaseRaf = 0
            }
        }
        const settleRelease = () => {
            d.extraRate = 0
            d.playing = true // embed 恆 resume(無 play/pause 鈕);onRelease≡'resume'
        }
        const rebaseToGrid = (targetTPos: number) => {
            d.tAmb = wrapTime(targetTPos, configRef.current!.duration)
            d.offset = 0
        }

        const runMomentum = (initialRate: number) => {
            stopRelease()
            const coastDuration =
                FLICK_MIN_DURATION +
                (MOMENTUM / 100) * (FLICK_MAX_DURATION - FLICK_MIN_DURATION)
            const coastT = getCoastT(coastDuration, CONTINUOUS_DECAY_EPS)
            const start = performance.now()
            let last = start
            const step = (now: number) => {
                const dt = Math.min((now - last) / 1000, 0.05)
                last = now
                const elapsed = (now - start) / 1000
                if (elapsed >= coastT) {
                    settleRelease()
                    releaseRaf = 0
                    return
                }
                const rate = rateAtElapsed(initialRate, elapsed, coastDuration)
                d.offset += rate * dt
                d.extraRate = rate
                releaseRaf = requestAnimationFrame(step)
            }
            releaseRaf = requestAnimationFrame(step)
        }
        const runFlick = (currentTPos: number, initialRate: number) => {
            stopRelease()
            const c = configRef.current!
            const coastDuration =
                FLICK_MIN_DURATION +
                (MOMENTUM / 100) * (FLICK_MAX_DURATION - FLICK_MIN_DURATION)
            const item = oneItemDelta()
            const dirSignLocal = c.direction === "reverse" ? -1 : 1
            const naturalDistance = (initialRate * coastDuration) / 3
            const maxDistance = item * MAX_FLICK_ITEMS
            const clampedDistance = Math.max(
                -maxDistance,
                Math.min(maxDistance, naturalDistance)
            )
            const naturalTarget = currentTPos + dirSignLocal * clampedDistance
            const snapTarget =
                item > 0
                    ? Math.round(naturalTarget / item) * item
                    : naturalTarget
            const fromOffset = d.offset
            const toOffset =
                fromOffset + dirSignLocal * (snapTarget - currentTPos)
            const coastT = getCoastT(coastDuration, STEP_DECAY_EPS)
            const amplitude = solveAmplitudeForDistance(
                toOffset - fromOffset,
                coastDuration,
                STEP_DECAY_EPS
            )
            const start = performance.now()
            let last = start
            const step = (now: number) => {
                const dt = Math.min((now - last) / 1000, 0.05)
                last = now
                const elapsed = (now - start) / 1000
                if (elapsed >= coastT) {
                    rebaseToGrid(snapTarget)
                    settleRelease()
                    releaseRaf = 0
                    return
                }
                const rate = rateAtElapsed(amplitude, elapsed, coastDuration)
                d.offset += rate * dt
                d.extraRate = rate
                releaseRaf = requestAnimationFrame(step)
            }
            releaseRaf = requestAnimationFrame(step)
        }
        const handleRelease = (initialRate: number) => {
            if (configRef.current!.motion === "step")
                runFlick(d.tPos, initialRate)
            else runMomentum(initialRate)
        }
        const watchIdle = () => {
            if (!d.isDragging) {
                idleRaf = 0
                return
            }
            if (performance.now() - d.lastMoveTime > IDLE_MS) {
                d.extraRate = 0
                d.lastRate = 0
            }
            idleRaf = requestAnimationFrame(watchIdle)
        }

        // 主 render/clock 迴圈(app: gsap.ticker;此處手動 rAF,同 embed)。
        // tPos/tAmb/dragVel 組合逐字抄自 useCardTransformTimeline.js。
        const frame = (now: number) => {
            const c = configRef.current!
            const dur = c.duration
            const dirSign = c.direction === "reverse" ? -1 : 1
            const dt = Math.min((now - d.clockLast) / 1000, 0.05)
            d.clockLast = now
            if (d.playing) d.tAmb = wrapTime(d.tAmb + dt, dur)
            const ambRate = d.playing ? 1 : 0
            const dragVel = ambRate + dirSign * d.extraRate - 1
            d.tPos = wrapTime(d.tAmb + dirSign * d.offset, dur)
            paint(c, d.tPos, d.tAmb, dragVel)
            raf = requestAnimationFrame(frame)
        }
        raf = requestAnimationFrame(frame)

        // ---- 事件層(僅 draggable 時綁定)----
        let removeDown: (() => void) | null = null
        let removeWheel: (() => void) | null = null
        let endInFlight: (() => void) | null = null
        if (draggable) {
            const onPointerDown = (e: PointerEvent) => {
                stopRelease()
                d.isDragging = true
                d.playing = false
                d.lastX = e.clientX
                d.lastMoveTime = performance.now()
                d.lastRate = 0
                try {
                    root.setPointerCapture(e.pointerId)
                } catch {}
                if (!idleRaf) idleRaf = requestAnimationFrame(watchIdle)
                // startDragSession + blur guard 等效:window 級 move/up/cancel +
                // blur —— 放手在視窗外、或視窗失焦,都能正確結束拖曳。
                const handleMove = (ev: PointerEvent) => {
                    if (!d.isDragging) return
                    const now = performance.now()
                    const dxPx = ev.clientX - d.lastX
                    const dtReal = Math.max(
                        (now - d.lastMoveTime) / 1000,
                        1 / 240
                    )
                    const dOffset = dxPx * deltaTPerPx()
                    d.offset += dOffset
                    const rate = dOffset / dtReal
                    d.lastRate = rate
                    d.extraRate = rate
                    d.lastX = ev.clientX
                    d.lastMoveTime = now
                }
                const end = () => {
                    window.removeEventListener("pointermove", handleMove)
                    window.removeEventListener("pointerup", end)
                    window.removeEventListener("pointercancel", end)
                    window.removeEventListener("blur", end)
                    endInFlight = null
                    if (!d.isDragging) return
                    d.isDragging = false
                    try {
                        root.releasePointerCapture(e.pointerId)
                    } catch {}
                    handleRelease(d.lastRate)
                }
                endInFlight = end
                window.addEventListener("pointermove", handleMove)
                window.addEventListener("pointerup", end)
                window.addEventListener("pointercancel", end)
                window.addEventListener("blur", end)
            }
            root.addEventListener("pointerdown", onPointerDown)
            removeDown = () =>
                root.removeEventListener("pointerdown", onPointerDown)

            // scroll:水平(deltaX)only,passive —— 縱向頁面捲動永不被 preventDefault。
            const onWheel = (e: WheelEvent) => {
                if (e.deltaX === 0) return
                stopRelease()
                clearTimeout(wheelTimer as ReturnType<typeof setTimeout>)
                if (!d.isDragging) d.playing = false
                d.isDragging = true
                const dOffset = e.deltaX * deltaTPerPx()
                d.offset += dOffset
                const rate = dOffset / (1 / 60)
                d.extraRate = rate
                wheelTimer = setTimeout(() => {
                    d.isDragging = false
                    handleRelease(rate)
                }, 120)
            }
            root.addEventListener("wheel", onWheel, { passive: true })
            removeWheel = () => root.removeEventListener("wheel", onWheel)
        }

        return () => {
            cancelAnimationFrame(raf)
            stopRelease()
            if (idleRaf) cancelAnimationFrame(idleRaf)
            clearTimeout(wheelTimer as ReturnType<typeof setTimeout>)
            removeDown?.()
            removeWheel?.()
            endInFlight?.() // 結束任何進行中的拖曳(移除 window 監聽)
        }
        // eslint-disable-next-line react-hooks/exhaustive-deps
    }, [isStatic, poolSize, draggable, paint])

    // ⚠️ 透視鏈忠實重建:frame(量測) → 設計畫布(contain fit + 置中) →
    //    offset(preserve-3d) → group(FLAT) → card。fit 是純外層縮放,不碰
    //    computeCardTransforms 數值(卡片仍在 1080 設計空間裡定位)。
    return (
        <div
            /* frame(量測外層 frame 寬高) */
            ref={rootRef}
            style={{
                position: "absolute",
                inset: 0 as any,
                overflow: "hidden",
                // 觸控:draggable 時用 pan-y —— 水平拖曳由本元件接管(pointer
                // 事件拿得到),縱向頁面捲動仍放行給瀏覽器。
                touchAction: draggable ? "pan-y" : "auto",
            }}
        >
            <div
                /* 設計畫布 DESIGN_W×designH(designH 跟隨 frame 比例 + 焦點卡地板):
                   contain 等比縮放 + 置中。overflow:hidden 對齊 app 的
                   .preview-canvas —— coverflow 在 zoom 下比設計畫布寬,側卡在
                   【設計畫布邊界】被裁(而非 frame 邊界),與 app 裁切形狀一致。 */
                style={{
                    position: "absolute",
                    left: "50%",
                    top: "50%",
                    width: DESIGN_W,
                    height: designH,
                    overflow: "hidden",
                    transform: `translate(-50%, -50%) scale(${fitScale})`,
                    transformOrigin: "center",
                }}
            >
                <div
                    /* .tpl-offset */
                    style={{
                        position: "absolute",
                        inset: 0 as any,
                        transformStyle: "preserve-3d",
                        transform: `translate(${LOCKED.offsetX}px, ${LOCKED.offsetY}px)`,
                    }}
                >
                    <div
                        /* .tpl-group —— flat override;zoom 走此層(總縮放 = fitScale × zoom/100) */
                        style={{
                            position: "absolute",
                            inset: 0 as any,
                            transformStyle: "flat",
                            transform: `scale(${zoom / 100})`,
                        }}
                    >
                        {Array.from({ length: poolSize }).map((_, i) => (
                            <div
                                /* .tpl-card */
                                key={i}
                                ref={(el) => {
                                    cardRefs.current[i] = el
                                }}
                                style={{
                                    position: "absolute",
                                    left: "50%", // 每幀被 el.style.left = `${tr.left}px` 覆蓋
                                    top: "50%",
                                    width: cardSize,
                                    height: cardHeight,
                                    borderRadius: cardRadius,
                                    overflow: "hidden",
                                    willChange: "transform, opacity",
                                }}
                            >
                                <img
                                    src={
                                        effectiveImages[
                                            i % effectiveImages.length
                                        ]
                                    }
                                    alt=""
                                    draggable={false}
                                    style={{
                                        width: "100%",
                                        height: "100%",
                                        objectFit: "cover",
                                        objectPosition: "center",
                                        display: "block",
                                        userSelect: "none",
                                    }}
                                />
                            </div>
                        ))}
                    </div>
                </div>
            </div>
        </div>
    )
}

// ----------------------------------------------------------------------
// Property controls —— Cards(圖片上傳)+ 7 個策展開放參數。
// 開放參數的 defaultValue = coverflow 預設 preset 的值(拖進來即該效果);
// min/max = coverflow schema.js 的已驗證安全值域。
// ----------------------------------------------------------------------
addPropertyControls(CoverflowSpike, {
    // 真正的圖片上傳:Array of Image —— 買家可上傳/增刪/排序,每張卡一個圖片欄位。
    images: {
        type: ControlType.Array,
        control: { type: ControlType.Image },
        title: "Cards",
        // 空 → 用內建預設示範圖(做法 B),元件拖進來立刻漂亮。
    },
    // coverflow preset count 15;schema 值域 3–30
    count: {
        type: ControlType.Number,
        title: "Count",
        min: 3,
        max: 30,
        step: 1,
        defaultValue: 15,
        displayStepper: true,
    },
    // coverflow preset cardSize 150;schema 值域 60–200
    cardSize: {
        type: ControlType.Number,
        title: "Card Size",
        min: 60,
        max: 200,
        step: 1,
        defaultValue: 150,
        unit: "px",
    },
    // coverflow preset gap −56;schema 值域 −80–40
    gap: {
        type: ControlType.Number,
        title: "Gap",
        min: -80,
        max: 40,
        step: 1,
        defaultValue: -56,
        unit: "px",
        description:
            "Space between cards. Negative values overlap them — the classic cover-flow stacked look.",
    },
    // coverflow preset duration 26;schema 值域 2–60
    duration: {
        type: ControlType.Number,
        title: "Duration",
        min: 2,
        max: 60,
        step: 1,
        defaultValue: 26,
        unit: "s",
        description:
            "Seconds for one full loop through all cards. Higher is slower.",
    },
    // coverflow preset zoom 267;schema 值域 50–300
    zoom: {
        type: ControlType.Number,
        title: "Zoom",
        min: 50,
        max: 300,
        step: 1,
        defaultValue: 267,
        unit: "%",
    },
    // coverflow preset cardRatio '1:1';schema enum
    cardRatio: {
        type: ControlType.Enum,
        title: "Card Ratio",
        options: ["1:1", "4:3", "3:4", "16:9", "9:16"],
        optionTitles: ["1:1", "4:3", "3:4", "16:9", "9:16"],
        defaultValue: "1:1",
        displaySegmentedControl: true,
    },
    // 策展參數:卡片圓角(直接 px 值,不影響 coverflow 性格,故開放)。
    cornerRadius: {
        type: ControlType.Number,
        title: "Corner Radius",
        min: 0,
        max: 40,
        step: 1,
        defaultValue: 12,
        unit: "px",
        description: "Rounds the corners of every card. 0 = sharp corners.",
    },
    // coverflow preset focusEmphasis 8;schema 值域 0–100
    focusEmphasis: {
        type: ControlType.Number,
        title: "Focus Emphasis",
        min: 0,
        max: 100,
        step: 1,
        defaultValue: 8,
        description:
            "How far the centered focus card pops toward the viewer (translateZ). 0 = flat, higher = more pop.",
    },
    // A-2 互動:拖曳/滾輪/慣性開關。預設 on;關掉回純自動播放。
    // 畫布靜止,拖曳只在 Preview / 發布後生效。
    draggable: {
        type: ControlType.Boolean,
        title: "Draggable",
        defaultValue: true,
        enabledTitle: "On",
        disabledTitle: "Off",
        description:
            "Drag, scroll, and flick with momentum (touch too). Off = autoplay only. Static on the canvas — dragging works in Preview and on the published site.",
    },
})
